-- KADR cinema schema, SQLite version 1
PRAGMA foreign_keys = ON;

CREATE TABLE users(id INTEGER PRIMARY KEY,username TEXT UNIQUE NOT NULL COLLATE NOCASE,full_name TEXT NOT NULL,password_hash TEXT NOT NULL,salt TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('ADMIN','USER')),active INTEGER NOT NULL DEFAULT 1,email TEXT NOT NULL DEFAULT '',phone TEXT NOT NULL DEFAULT '');

CREATE TABLE sessions(token_hash TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),expires_at INTEGER NOT NULL);

CREATE TABLE movies(id INTEGER PRIMARY KEY,title TEXT NOT NULL,genre TEXT NOT NULL,duration INTEGER NOT NULL CHECK(duration BETWEEN 30 AND 300),age INTEGER NOT NULL,synopsis TEXT NOT NULL,director TEXT NOT NULL,year INTEGER NOT NULL,art INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1);

CREATE TABLE halls(id INTEGER PRIMARY KEY,name TEXT UNIQUE NOT NULL COLLATE NOCASE,rows_count INTEGER NOT NULL CHECK(rows_count BETWEEN 3 AND 12),cols_count INTEGER NOT NULL CHECK(cols_count BETWEEN 4 AND 12),active INTEGER NOT NULL DEFAULT 1);

CREATE TABLE shows(id INTEGER PRIMARY KEY,movie_id INTEGER NOT NULL REFERENCES movies(id),hall_id INTEGER NOT NULL REFERENCES halls(id),starts_at INTEGER NOT NULL,ends_at INTEGER NOT NULL,price INTEGER NOT NULL CHECK(price BETWEEN 0 AND 100000),format TEXT NOT NULL,language TEXT NOT NULL,rows_count INTEGER NOT NULL,cols_count INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'ACTIVE');

CREATE INDEX shows_time ON shows(starts_at,status);

CREATE TABLE bookings(id INTEGER PRIMARY KEY,code TEXT NOT NULL UNIQUE,user_id INTEGER NOT NULL REFERENCES users(id),show_id INTEGER NOT NULL REFERENCES shows(id),created_at INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'BOOKED',movie_title TEXT NOT NULL,hall_name TEXT NOT NULL,starts_at INTEGER NOT NULL,seats TEXT NOT NULL,total INTEGER NOT NULL,format TEXT NOT NULL,promo TEXT NOT NULL DEFAULT '',discount INTEGER NOT NULL DEFAULT 0);

CREATE INDEX bookings_user ON bookings(user_id,created_at);

CREATE TABLE booking_seats(booking_id INTEGER NOT NULL REFERENCES bookings(id),show_id INTEGER NOT NULL REFERENCES shows(id),row_no INTEGER NOT NULL,seat_no INTEGER NOT NULL,UNIQUE(show_id,row_no,seat_no));

CREATE TABLE favorites(user_id INTEGER NOT NULL REFERENCES users(id),movie_id INTEGER NOT NULL REFERENCES movies(id),PRIMARY KEY(user_id,movie_id));

CREATE TABLE reviews(user_id INTEGER NOT NULL REFERENCES users(id),movie_id INTEGER NOT NULL REFERENCES movies(id),score INTEGER NOT NULL CHECK(score BETWEEN 1 AND 5),comment TEXT NOT NULL,updated_at INTEGER NOT NULL,PRIMARY KEY(user_id,movie_id));

CREATE TABLE promos(code TEXT PRIMARY KEY COLLATE NOCASE,percent INTEGER NOT NULL CHECK(percent BETWEEN 1 AND 90),active INTEGER NOT NULL DEFAULT 1);
